def eval_with_tv(rules, atoms, tv):
    amap = {a: i for i, a in enumerate(atoms)}

    def ev(e):
        op = e["op"]
        if op == "true":
            return True
        if op == "false":
            return False
        if op in ("match", "startswith", "endswith", "contains"):
            return tv[amap[(op, tuple(e["path"]))]]
        if op == "not":
            return not ev(e["arg"])
        if op == "and":
            return all(ev(a) for a in e["args"])
        return any(ev(a) for a in e["args"])

    allowed = False
    dropped = False
    for r in rules:
        v = ev(r["when"])
        if r["action"] == "allow":
            allowed = allowed or v
        else:
            dropped = dropped or v
    return allowed and not dropped
